    raise ValueError(
        "The overlap CSV does not correspond to the selected original "
        "POI CSV files. Select the same two source files that were used "
        "to create the overlap CSV."
    )

overlap_count = len(
    overlap_dataframe
)

# Confirm one source row was found for every overlap on both sides.
if len(matched_first_ids) != overlap_count:
    raise ValueError(
        "The number of first-dataset matches differs from the overlap count."
