# =============================================================================

first_unique_dataframe = first_dataframe[
    ~first_dataframe[
        "_source_row_id"
    ].isin(
        matched_first_ids
    )
].copy()

second_unique_dataframe = second_dataframe[
    ~second_dataframe[
        "_source_row_id"
    ].isin(
        matched_second_ids
    )
].copy()

first_total = len(
