        ],
        "second_end": overlap_row[
            "second_end"
        ],
        "second_position": overlap_row[
            "second_position"
        ],
        "distance_bp": overlap_row[
            "distance_bp"
        ],
    }

    # Preserve extra columns already present in the overlap CSV.
    for column in overlap_dataframe.columns:
        if column in output_row:
            continue

        # Internal source indices are not included in the membership output.
        if column in {
            "first_index",
            "second_index",
        }:
            continue

        output_row[column] = (
            overlap_row.get(
                column,
                np.nan,
            )
        )

    membership_rows.append(
        output_row
    )


# -----------------------------------------------------------------------------
